import sys
from math import comb


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    values = data[1:]
    values.sort()

    threshold = values[2]
    smaller = 0
    equal = 0

    for value in values:
        if value < threshold:
            smaller += 1
        elif value == threshold:
            equal += 1
        else:
            break

    print(comb(equal, 3 - smaller))


if __name__ == "__main__":
    main()
